if (!jobFile) { console.error("用法：node tools/dev/patch-literal.js jobs.json [--keep-bak|--fresh-bak]"); process.exit(2); }
/* 备份策略（bf-12 翻转默认）：
     默认        = **刷新**：写之前把旧备份删掉、重拷当前磁盘版本 → 备份 = 「本次改前」那一版，
                   语法闸回滚只退本次改动（不会连上一轮的好改动一起退掉）。
     --keep-bak  = 旧默认：备份已存在就不动 → 备份 = 「第一次改前」那一版。
     --fresh-bak = 显式声明默认行为；老脚本 / 老文档里写着它，继续接受，与默认等价。 */
const KEEP_BAK = process.argv.indexOf("--keep-bak") >= 0;
const FRESH_FLAG = process.argv.indexOf("--fresh-bak") >= 0;
if (KEEP_BAK && FRESH_FLAG) { console.error("✗ --keep-bak 与 --fresh-bak 互斥，只能写一个"); process.exit(2); }
const FRESH = !KEEP_BAK;
console.log("· 备份模式：" + (FRESH ? "刷新（默认：备份 = 本次改前那一版）" : "保留（--keep-bak：备份 = 第一次改前那一版）"));

