/* 落盘（先备份）。默认**每次刷新**备份 → 备份永远是「本次改前」那一版，
   所以下面语法闸回滚只会退回本次改动；--keep-bak 时保留第一次的备份（旧语义）。 */
const written = [];
for (const [file, e] of plan) {
  const bak = file + BAK;
  if (FRESH) {
    if (fs.existsSync(bak)) fs.rmSync(bak);
    fs.copyFileSync(file, bak);
    console.log("· 备份 → " + path.basename(bak) + "（已刷新 = 本次改前那一版）");
  } else if (!fs.existsSync(bak)) {
    fs.copyFileSync(file, bak);
    console.log("· 备份 → " + path.basename(bak) + "（新建 = 第一次改前那一版）");
  } else {
    console.log("· 备份 → " + path.basename(bak) + "（保留 = 第一次改前那一版 · --keep-bak）");
  }
  fs.writeFileSync(file, e.next);
  written.push(file);
}
